// changes that start within the range and base content (equal to the
// side's, since unmatched only where a change is) everywhere else.
function resolveSide(changes, base, side, start, end) {
  const result = []
  let pos = start
  for (const c of changes) {
    if (c.baseStart < start || c.baseStart >= end) continue
    result.push(...base.slice(pos, c.baseStart))
    result.push(...side.slice(c.sideStart, c.sideEnd))
    pos = c.baseEnd
  }
  result.push(...base.slice(pos, end))
  return result
