  let pos = 0
  let idx = 0
  while (idx < allChanges.length) {
    const first = allChanges[idx]
    if (first.baseStart > pos) {
      regions.push({ kind: 'stable', lines: base.slice(pos, first.baseStart) })
    }
    const start = first.baseStart
    let end = first.baseEnd
    idx++
    while (idx < allChanges.length && allChanges[idx].baseStart <= end) {
      end = Math.max(end, allChanges[idx].baseEnd)
      idx++
    }

    const mineLines = resolveSide(mineChanges, base, mine, start, end)
    const theirsLines = resolveSide(theirsChanges, base, theirs, start, end)
    const baseLines = base.slice(start, end)

