import { parseInput } from './parseInput.js'
import { buildRegions } from './mergeRegions.js'
import { formatMerge, formatRegions } from './output.js'

const MODES = ['merge', 'merge2', 'regions']

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', chunk => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.includes(mode)) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }

  const raw = await readStdin()
  const docs = parseInput(raw)
  if (docs === null) {
    fail('expected three parts separated by %%%')
    return
  }

  const [mine, base, theirs] = docs
  const regions = buildRegions(mine, base, theirs)
  const { text, conflict } = mode === 'regions' ? formatRegions(regions) : formatMerge(regions, mode === 'merge')

  process.stdout.write(text)
  process.exitCode = conflict ? 1 : 0
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exitCode = 2
})
